"use client";

/* eslint-disable @next/next/no-img-element -- user-supplied native PNG sources */
import {useEffect,useId,useMemo,useRef,useState} from 'react';
import {RECENT_SPRITE_LIBRARY_V85,RECENT_SPRITE_ASSETS_V85,RECENT_SPRITE_KINDS_V85,
 normalizeRecentSpriteTextV85,type RecentSpriteSourceV85} from './systems/recentSpriteLibraryV85';
import {RECENT_SPRITE_CODEX_V85} from './systems/recentSpriteCodexV85';
import styles from './RecentSpriteLibraryV85.module.css';

const PAGE_SIZE=18;
function SourceImageV85({asset,thumbnail=false}:{asset:RecentSpriteSourceV85;thumbnail?:boolean}){
 const[status,setStatus]=useState<'loading'|'ready'|'error'>('loading');
 // Very tall source sheets can exceed 50 million pixels. Keep their native
 // bytes accessible without decoding several of them just by opening a page.
 const largeReference=asset.kind==='reference'&&asset.width*asset.height>12_000_000;
 const[requested,setRequested]=useState(!largeReference);
 if(largeReference&&thumbnail)return<div className={styles.thumbnail}><p className={styles.imageStatus}>Planche originale<br/>{asset.width} × {asset.height}</p></div>;
 if(!requested)return<div className={styles.imageSurface}><p className={styles.imageStatus}>Source entière de grand format ({asset.width} × {asset.height}). Elle est conservée sans découpage. Son chargement peut demander beaucoup de mémoire.</p><button type="button" onClick={()=>setRequested(true)}>Afficher cette source grand format</button></div>;
 return<div className={thumbnail?styles.thumbnail:styles.imageSurface} data-source-status-v85={status}>
  <img src={asset.src} alt={thumbnail?'':asset.label} width={asset.width||1024} height={asset.height||1536}
   loading={thumbnail?'lazy':'eager'} decoding="async" hidden={status==='error'} onLoad={()=>setStatus('ready')} onError={()=>setStatus('error')}/>
  {status==='error'&&<p className={styles.imageStatus}>Source indisponible à cet emplacement.</p>}
  {!thumbnail&&status==='loading'&&<p className={styles.imageStatus} role="status">Chargement de l’image…</p>}
 </div>;
}

/** Read-only source library. Root owns opening, closing and pausing the game;
 * this panel owns filters/focus and never mutates progression or character art. */
export default function RecentSpriteLibraryV85({onClose}:{onClose:()=>void}){
 const titleId=useId(),panel=useRef<HTMLElement>(null),closeButton=useRef<HTMLButtonElement>(null);
 const[query,setQuery]=useState(''),[kind,setKind]=useState(''),[pack,setPack]=useState(''),[group,setGroup]=useState('');
 const[includeHistory,setIncludeHistory]=useState(false),[page,setPage]=useState(0),[selectedId,setSelectedId]=useState('');
 useEffect(()=>{const previous=document.activeElement instanceof HTMLElement?document.activeElement:null;closeButton.current?.focus();
  const keydown=(event:KeyboardEvent)=>{if(event.key==='Escape'){event.preventDefault();onClose();return;}
   if(event.key!=='Tab')return;const controls=Array.from(panel.current?.querySelectorAll<HTMLElement>('button:not([disabled]), input, select, a[href]')??[]),first=controls[0],last=controls.at(-1);
   if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}
  };window.addEventListener('keydown',keydown);return()=>{window.removeEventListener('keydown',keydown);previous?.focus();};
 },[onClose]);
 const groups=useMemo(()=>Array.from(new Map(RECENT_SPRITE_ASSETS_V85.map(asset=>[asset.groupId,asset.groupLabel])).entries()).sort((a,b)=>a[1].localeCompare(b[1],'fr')),[]);
 const results=useMemo(()=>{const search=normalizeRecentSpriteTextV85(query);
  return RECENT_SPRITE_ASSETS_V85.filter(asset=>(includeHistory||asset.preferredVersion)&&(!kind||asset.kind===kind)&&(!pack||asset.packId===pack)&&(!group||asset.groupId===group)
   &&(!search||normalizeRecentSpriteTextV85(`${asset.label} ${asset.groupLabel} ${asset.roleLabel} ${asset.identityId} ${asset.sourceStatus} ${asset.sourcePath}`).includes(search)));
 },[query,kind,pack,group,includeHistory]);
 const currentPage=Math.min(page,Math.max(0,Math.ceil(results.length/PAGE_SIZE)-1)),visible=results.slice(currentPage*PAGE_SIZE,(currentPage+1)*PAGE_SIZE);
 const selected=results.find(asset=>asset.id===selectedId)??visible[0],record=selected?RECENT_SPRITE_CODEX_V85.find(item=>item.source.id===selected.id):null;
 const resetPage=()=>{setPage(0);setSelectedId('');};
 return<div className={styles.overlay}><section ref={panel} className={styles.library} role="dialog" aria-modal="true" aria-labelledby={titleId} data-recent-sprite-library-v85="true">
  <header className={styles.header}><div><p className={styles.eyebrow}>SOURCES FOURNIES · OCTOBRE 2026</p><h2 id={titleId}>Personnages, faune et matériaux</h2></div><button ref={closeButton} type="button" onClick={onClose} aria-label="Fermer la bibliothèque">Fermer</button></header>
  <p>Consultez les variantes documentées par clan, lignée et fonction. Les images sont présentées dans leur orientation d’origine ; les poses fixes et les versions antérieures gardent leur fiche source.</p>
  <p className={styles.notice}>{RECENT_SPRITE_LIBRARY_V85.uniqueReferencedHashes.toLocaleString('fr')} empreintes natives distinctes référencées, dont {RECENT_SPRITE_LIBRARY_V85.nativeEnforcerFilesV611} Enforcers V6.11, {RECENT_SPRITE_LIBRARY_V85.nativeEnforcerFilesV612} Enforcers V6.12, {RECENT_SPRITE_LIBRARY_V85.nativeEnforcerFilesV613} Enforcers V6.13, {RECENT_SPRITE_LIBRARY_V85.nativeRecoveredFilesV87} PNG récupérés en V87, {RECENT_SPRITE_LIBRARY_V85.nativeRecoveredFilesV88} planches historiques retrouvées en V88, {RECENT_SPRITE_LIBRARY_V85.nativeReferenceFilesV89} références Badlands ajoutées en V89 et les {RECENT_SPRITE_LIBRARY_V85.nativeGarrisonFilesV86} individus de garnison V6.8. Les poses fixes, cavaliers assemblés, illustrations et reconstitutions restent identifiés comme tels ; aucune nouvelle animation n’est déduite d’un PNG.</p>
  <div className={styles.filters}>
   <label>Rechercher<input type="search" value={query} maxLength={120} placeholder="Clan, rôle, Kalisk, texture…" onChange={event=>{setQuery(event.target.value);resetPage();}}/></label>
   <label>Famille<select value={kind} onChange={event=>{setKind(event.target.value);resetPage();}}><option value="">Toutes les familles</option>{RECENT_SPRITE_KINDS_V85.map(item=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label>
   <label>Pack<select value={pack} onChange={event=>{setPack(event.target.value);resetPage();}}><option value="">Tous les packs</option>{RECENT_SPRITE_LIBRARY_V85.packs.filter(item=>item.pngEntriesImported>0).map(item=><option key={item.id} value={item.id}>{item.label}</option>)}</select></label>
   <label>Clan ou groupe<select value={group} onChange={event=>{setGroup(event.target.value);resetPage();}}><option value="">Tous les groupes</option>{groups.map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label>
  </div>
  <label className={styles.history}><input type="checkbox" checked={includeHistory} onChange={event=>{setIncludeHistory(event.target.checked);resetPage();}}/>Inclure les anciennes versions et sources provisoires</label>
  <p className={styles.count} role="status" aria-live="polite">{results.length.toLocaleString('fr')} fiche(s) · page {results.length?currentPage+1:0} sur {Math.ceil(results.length/PAGE_SIZE)}</p>
  {selected&&<figure className={styles.viewer} data-selected-sprite-v85={selected.id}>
   <SourceImageV85 key={selected.id} asset={selected}/><figcaption><div><h3>{selected.label}</h3><p>{selected.groupLabel} · {selected.roleLabel||selected.kind} · {selected.version}</p>
    <p>{selected.width} × {selected.height} · {selected.pose}</p><p className={styles.status}>Statut source : {selected.sourceStatus}{selected.producerStatus?' · '+selected.producerStatus:''}</p>
    <p>{selected.sourceNote}</p><p>{selected.sourceArchive}{selected.insideArchive?' → '+selected.insideArchive:''}</p>
    <details><summary>Identité et provenance</summary><p>Identité : {selected.identityId}</p><p>Fichier : {selected.sourcePath}</p><p className={styles.hash}>SHA256 {selected.sha256}</p>
     {record&&<ul>{record.constraints.map((constraint,index)=><li key={index}>{constraint}</li>)}</ul>}
     {!!record?.historicalVariants.length&&<p>Autres fiches de cette identité : {record.historicalVariants.length}. Activez l’historique pour les consulter.</p>}
    </details></div><a href={selected.src} target="_blank" rel="noopener noreferrer">Image originale</a></figcaption>
  </figure>}
  <div className={styles.grid}>{visible.map(asset=><button type="button" key={asset.id} className={styles.card} aria-pressed={asset.id===selected?.id} onClick={()=>setSelectedId(asset.id)}>
   <SourceImageV85 asset={asset} thumbnail/><strong>{asset.label}</strong><small>{asset.groupLabel} · {asset.version}</small><small>{asset.preferredVersion?'Version préférée de cette identité':'Version conservée ou provisoire'}</small>
  </button>)}</div>
  {!results.length&&<p>Aucune source ne correspond à ces filtres. <button type="button" onClick={()=>{setQuery('');setKind('');setPack('');setGroup('');resetPage();}}>Réinitialiser</button></p>}
  {results.length>PAGE_SIZE&&<nav className={styles.pagination} aria-label="Pages de la bibliothèque"><button type="button" disabled={currentPage===0} onClick={()=>{setPage(currentPage-1);setSelectedId('');}}>Page précédente</button><button type="button" disabled={(currentPage+1)*PAGE_SIZE>=results.length} onClick={()=>{setPage(currentPage+1);setSelectedId('');}}>Page suivante</button></nav>}
  <footer className={styles.footer}>L’archive V85 conserve les {RECENT_SPRITE_LIBRARY_V85.summary.metadataOnlyNpcVariants} fiches documentaires du pack PNJ V84. Les 640 PNG originaux restaurés sont consultables dans la galerie des variantes V84. Ces dessins sont des poses fixes ; les cycles natifs de marche et les autres animations conservent leurs systèmes dédiés.</footer>
 </section></div>;
}

import source from '../data/recentSpriteLibraryV85.json';
import driveLatest from '../data/driveLatestSpritesV85.json';
import badlandsLatest from '../data/badlandsLatestSpritesV85.json';
import approvedHunters from '../data/recentApprovedHuntersV85.json';
import driveGarrisons from '../data/driveGarrisonsV86.json';
import driveCompletion from '../data/driveCompletionSpritesV87.json';
import driveArchiveAudit from '../data/driveArchiveAuditSpritesV87.json';
import driveNewDeposits from '../data/driveNewDepositsSpritesV87.json';
import driveHistoricalRecoveryV88 from '../data/driveNewDepositsSpritesV88.json';
import driveReferenceRecoveryV89 from '../data/driveNewDepositsSpritesV89.json';
import enforcerProductionV611 from '../data/enforcerProductionV611.json';
import enforcerProductionV612 from '../data/enforcerProductionV612.json';
import enforcerProductionV613 from '../data/enforcerProductionV613.json';
import npcMetadata from '../data/recentNpcSourceMetadataV85.json';

export type RecentSpriteKindV85='npc'|'fauna'|'flora'|'synthetic'|'texture'|'ship'|'equipment'|'reference';
export interface RecentSpriteSourceV85 {
 readonly id:string;readonly identityId:string;readonly label:string;readonly packId:string;readonly packLabel:string;
 readonly version:string;readonly priority:number;readonly preferredVersion:boolean;readonly kind:RecentSpriteKindV85;
 readonly groupId:string;readonly groupLabel:string;readonly role:string;readonly roleLabel:string;readonly lifeStage:string;
 readonly regionId:string;readonly morphotypeId:string;readonly masked:string;readonly src:string;
 readonly width:number;readonly height:number;readonly bytes:number;readonly sha256:string;readonly sourceArchive:string;
 readonly insideArchive:string|null;readonly sourcePath:string;readonly sourceStatus:string;readonly producerStatus:string;
 readonly pose:string;readonly motionStatus:'single-pose-static';readonly canonicalFidelity:'not-certified-1-to-1';readonly sourceNote:string;
 readonly supersedesIdentityId:string;readonly supersededByIdentityId:string;
 readonly canonicalSubject?:string|null;readonly canonicalState?:string|null;readonly fullBody?:boolean|null;
 readonly bodyComposition?:'single-individual'|'rider-and-mount'|'reference-image';
 readonly sourceLimits?:readonly string[];
 readonly nativeNature?:string;
}
/** Original imported pixels and their historical versions. This registry never
 * starts a pack script, grants a reward, swaps a costume or synthesizes frames. */
export interface DriveLatestSpriteEntryV85 {
 readonly id:string;readonly label:string;readonly src:string;readonly width:number;readonly height:number;readonly sha256:string;readonly bytes:number;
 readonly kind:RecentSpriteKindV85;readonly groupId:string;readonly groupLabel?:string;readonly role?:string;
 readonly sourceArchive:string;readonly sourcePath:string;readonly sourceStatus:string;readonly producerStatus?:string;
 readonly sourceNote?:string;readonly preferredVersion?:boolean;
 readonly identityId?:string;readonly packId?:string;readonly packLabel?:string;readonly version?:string;readonly priority?:number;
 readonly pose?:string;readonly supersedesIdentityId?:string;readonly supersededByIdentityId?:string;
 readonly canonicalSubject?:string|null;readonly canonicalState?:string|null;readonly fullBody?:boolean|null;
}
const normalizeDriveEntryV85=(asset:DriveLatestSpriteEntryV85):RecentSpriteSourceV85=>({
 ...asset,identityId:asset.identityId??asset.id,packId:asset.packId??'drive-latest',packLabel:asset.packLabel??'Derniers fichiers Drive · 7 octobre',version:asset.version??'2026-10-07',priority:asset.priority??85,
 preferredVersion:!/reject|attempt|provis|pending|essai|brouillon/i.test(`${asset.sourceStatus} ${asset.producerStatus??''}`)&&(asset.preferredVersion??true),
 groupLabel:asset.groupLabel??asset.groupId,role:asset.role??'',roleLabel:asset.role??'',lifeStage:'',regionId:'',morphotypeId:'',masked:'',insideArchive:null,
 producerStatus:asset.producerStatus??'',pose:asset.pose??'Source native statique',motionStatus:'single-pose-static',canonicalFidelity:'not-certified-1-to-1',
 sourceNote:asset.sourceNote??'Fichier fourni récent ; statut de la source conservé et fidélité 1:1 non certifiée.',supersedesIdentityId:asset.supersedesIdentityId??'',supersededByIdentityId:asset.supersededByIdentityId??'',
});
const driveEntriesV85=(driveLatest.assets as readonly DriveLatestSpriteEntryV85[]).map(normalizeDriveEntryV85);
const badlandsEntriesV85=(badlandsLatest.assets as readonly DriveLatestSpriteEntryV85[]).map(normalizeDriveEntryV85);
const approvedHunterEntriesV85=(approvedHunters.assets as readonly DriveLatestSpriteEntryV85[]).map(normalizeDriveEntryV85);
// Complete original records carry documented role, age and morphology fields.
// Do not normalize these away like an unstructured individual Drive image.
const garrisonEntriesV86=driveGarrisons.assets as readonly RecentSpriteSourceV85[];
const completionEntriesV87=driveCompletion.assets as readonly RecentSpriteSourceV85[];
const archiveAuditEntriesV87=driveArchiveAudit.assets as readonly RecentSpriteSourceV85[];
const newDepositsEntriesV87=driveNewDeposits.assets as readonly RecentSpriteSourceV85[];
const historicalRecoveryEntriesV88=driveHistoricalRecoveryV88.assets as readonly RecentSpriteSourceV85[];
const referenceRecoveryEntriesV89=driveReferenceRecoveryV89.assets as readonly RecentSpriteSourceV85[];
const enforcerEntriesV611=enforcerProductionV611.assets as readonly RecentSpriteSourceV85[];
const enforcerEntriesV612=enforcerProductionV612.assets as readonly RecentSpriteSourceV85[];
const enforcerEntriesV613=enforcerProductionV613.assets as readonly RecentSpriteSourceV85[];
const supersededBadlandsV85=new Map<string,string>();
for(const asset of [...badlandsEntriesV85,...completionEntriesV87])if(asset.supersedesIdentityId)supersededBadlandsV85.set(asset.supersedesIdentityId,asset.identityId);
for(const note of [...badlandsLatest.sourceCorrectionNotes,...driveCompletion.sourceCorrectionNotes] as readonly {id:number;fields?:{superseded_by_asset_id?:number;morphology_corrected_by_asset_id?:number}}[]){
 const replacement=note.fields?.superseded_by_asset_id??note.fields?.morphology_corrected_by_asset_id;
 if(replacement)supersededBadlandsV85.set('badlands-'+note.id,'badlands-'+replacement);
}
/** Corrections change only reference preference. Superseded files retain their
 * source ID, pixels and catalogue entry, without a body or animation override. */
export const RECENT_SPRITE_ASSETS_V85:readonly RecentSpriteSourceV85[]=[...source.assets as readonly RecentSpriteSourceV85[],...driveEntriesV85,...badlandsEntriesV85,...approvedHunterEntriesV85,...garrisonEntriesV86,...completionEntriesV87,...archiveAuditEntriesV87,...newDepositsEntriesV87,...historicalRecoveryEntriesV88,...referenceRecoveryEntriesV89,...enforcerEntriesV611,...enforcerEntriesV612,...enforcerEntriesV613].map(asset=>{
 const replacement=supersededBadlandsV85.get(asset.identityId);return replacement?{...asset,preferredVersion:false,supersededByIdentityId:replacement}:asset;
});
export const RECENT_SPRITE_LIBRARY_V85={...source,assets:RECENT_SPRITE_ASSETS_V85,
 nativeGarrisonFilesV86:driveGarrisons.summary.nativePngFiles,
 nativeRecoveredFilesV87:driveCompletion.summary.newDistinctPngFiles+driveArchiveAudit.summary.newDistinctPngFiles+driveNewDeposits.summary.newDistinctPngFiles,
 nativeRecoveredFilesV88:driveHistoricalRecoveryV88.summary.newDistinctPngFiles,
 nativeReferenceFilesV89:driveReferenceRecoveryV89.summary.newReferencePngFiles,
 nativeEnforcerFilesV611:enforcerProductionV611.summary.nativePngFiles,
 nativeEnforcerFilesV612:enforcerProductionV612.summary.nativePngFiles,
 nativeEnforcerFilesV613:enforcerProductionV613.summary.nativePngFiles,
 uniqueReferencedHashes:new Set(RECENT_SPRITE_ASSETS_V85.map(asset=>asset.sha256)).size,
 packs:[...source.packs,{id:'drive-latest',label:'Derniers fichiers Drive · 7 octobre',version:'2026-10-07',priority:85,archive:'Fichiers Drive reçus individuellement',insideArchive:null,sha256:'',pngEntriesImported:driveEntriesV85.length,recordEntries:0,status:'source-import-authored-no-qa'},
  {id:'badlands-latest',label:'Badlands · ajouts V8 à V13',version:'V8–V13',priority:93,archive:'Six lots d’ajouts Drive',insideArchive:null,sha256:'',pngEntriesImported:badlandsEntriesV85.length,recordEntries:6,status:'source-import-authored-no-qa'},
  {id:'approved-hunters',label:'Portraits et créatures · sources récentes',version:'V14 / Wolf V1 profil V2',priority:94,archive:'Drive · dossier images validées PHG',insideArchive:null,sha256:'',pngEntriesImported:approvedHunterEntriesV85.length,recordEntries:7,status:'source-import-authored-no-qa'},...driveGarrisons.packs,...driveCompletion.packs,...driveArchiveAudit.packs,...driveNewDeposits.packs,...driveHistoricalRecoveryV88.packs,...driveReferenceRecoveryV89.packs,...enforcerProductionV611.packs,...enforcerProductionV612.packs,...enforcerProductionV613.packs]};
export const RECENT_SPRITE_PREFERRED_V85=RECENT_SPRITE_ASSETS_V85.filter(asset=>asset.preferredVersion);
export const RECENT_SPRITE_GROUPS_V85=source.groups;
export const RECENT_NPC_SOURCE_METADATA_V85=npcMetadata;
export const RECENT_NPC_SOURCE_ROLES_V85=npcMetadata.sourceRoles;
/** A producer metadata record does not prove its referenced PNG is installed.
 * The missing V84 pixels stay distinct from the imported native asset registry. */
export function documentedRecentNpcVariantV85(role:string,slot:number){
 const variant=npcMetadata.sourceVariants.find(item=>item.role===role&&item.slot===slot);
 return variant?{variant,sourceArchive:npcMetadata.sourceArchive,status:'metadata-only-pixels-not-in-archive' as const,availableForRender:false as const}:null;
}
export const RECENT_SPRITE_KINDS_V85:readonly {id:RecentSpriteKindV85;label:string}[]=[
 {id:'npc',label:'Personnages et cavaliers'},{id:'fauna',label:'Faune'},{id:'flora',label:'Flore'},
 {id:'synthetic',label:'Synthétiques'},{id:'texture',label:'Matériaux Hunting Grounds'},
 {id:'ship',label:'Coques et vaisseaux'},
 {id:'equipment',label:'Équipements et portions isolées'},
 {id:'reference',label:'Illustrations et références historiques'},
];
export const recentSpriteByIdV85=(id:string)=>RECENT_SPRITE_ASSETS_V85.find(asset=>asset.id===id)??null;
export const recentSpriteVariantsV85=(identityId:string)=>RECENT_SPRITE_ASSETS_V85.filter(asset=>asset.identityId===identityId);
export const normalizeRecentSpriteTextV85=(value:string)=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr').replace(/[^a-z0-9]+/g,' ').trim();

const aliases:Readonly<Record<string,readonly string[]>>={
 patrouille:['patrouille','patrouilleur'],
 pisteur:['pisteur','traqueur','tracker'],
 tireur:['tireur','sniper','gunner','artilleur'],
 sapeur:['sapeur','sapper','demolisseur','demolition'],
 soigneur:['soigneur','soigneuse','soin','soins','healer','medic'],
 porteur:['porteur','porteuse','porter','convoyeur','convoyeuse','ravitailleur','ravitaillement','transport'],
};
export interface ImportedYautjaArtV85 {
 readonly portraitUrl:string;readonly spriteUrl:string;readonly assetId:string;readonly source:string;
 readonly label:string;readonly groupId:string;readonly role:string;readonly match:'documented-name'|'documented-role'|'documented-clan';
 readonly motionStatus:'single-pose-static';
}

/** Match only catalogue identities. A named person needs their documented name;
 * a requested role needs a documented role/occupation in the same exact clan.
 * If absent, return null rather than assign an unrelated portrait or lineage. */
export interface ImportedYautjaArtQueryV85 {readonly clanName?:string;readonly role?:string;readonly name?:string;readonly identityId?:string;readonly assetId?:string;readonly includeHistorical?:boolean}
/** Historical choices remain explicit: no older PNG is deleted and a chosen
 * identity can never fall back to another costume, clan or named person. */
export function importedYautjaArtVariantsV85({clanName,role,name,identityId,assetId,includeHistorical=false}:ImportedYautjaArtQueryV85):readonly RecentSpriteSourceV85[]{
 const clan=clanName?normalizeRecentSpriteTextV85(clanName):'',person=name?normalizeRecentSpriteTextV85(name):'',requested=role?normalizeRecentSpriteTextV85(role):'';
 if(!clan&&!person&&!requested&&!identityId&&!assetId)return[];
 const roleTerms=aliases[requested]??(requested?[requested]:[]);
 // The accepted humans remain searchable archive NPCs, but their documented
 // human bodies must never be borrowed by a Yautja-only runtime consumer.
 const nonIndividualRoles=new Set(['monture','montures','monture seule','chevaucheur','chevaucheurs']);
 // A composed rider needs a dedicated mounted renderer and footprint. It
 // cannot supply a walking individual's body, even by explicit source ID.
 const candidates=RECENT_SPRITE_ASSETS_V85.filter(asset=>asset.kind==='npc'&&asset.groupId!=='human-accepted'&&asset.bodyComposition!=='rider-and-mount'
  &&!nonIndividualRoles.has(normalizeRecentSpriteTextV85(asset.role))&&!/--monture-seule-/.test(asset.identityId)&&(includeHistorical||asset.preferredVersion)
  &&(!identityId||asset.identityId===identityId)&&(!assetId||asset.id===assetId)
  &&(!clan||normalizeRecentSpriteTextV85(asset.groupLabel)===clan||normalizeRecentSpriteTextV85(asset.groupId)===clan)
  &&(!person||normalizeRecentSpriteTextV85(asset.label)===person));
 const scored=candidates.map(asset=>{
  // A clan's name or a display label never establishes a person's job.
  // Whole normalized words also prevent a partial term borrowing another role.
  const text=` ${normalizeRecentSpriteTextV85(`${asset.role} ${asset.roleLabel}`)} `,score=roleTerms.reduce((best,term)=>Math.max(best,text.includes(` ${normalizeRecentSpriteTextV85(term)} `)?term===requested?3:2:0),0);
  return{asset,score};
 }).filter(row=>!requested||row.score>0).sort((a,b)=>b.score-a.score||b.asset.priority-a.asset.priority||a.asset.id.localeCompare(b.asset.id));
 return scored.map(row=>row.asset);
}
export function findImportedYautjaArtV85(query:ImportedYautjaArtQueryV85):ImportedYautjaArtV85|null{
 const asset=importedYautjaArtVariantsV85(query)[0];if(!asset)return null;
 return{portraitUrl:asset.src,spriteUrl:asset.src,assetId:asset.id,source:`${asset.sourceArchive}${asset.insideArchive?' → '+asset.insideArchive:''} · ${asset.sourcePath}`,
  label:asset.label,groupId:asset.groupId,role:asset.role,match:query.name||query.identityId||query.assetId?'documented-name':query.role?'documented-role':'documented-clan',motionStatus:'single-pose-static'};
}

/** Exact known Badlands catalogue labels provide additional static references.
 * An adult, juvenile and a different costume stay separate source identities.
 * No combat collider, spawn, companion ability or animation is changed here. */
const faunaNames:Readonly<Record<string,readonly string[]>>={
 kalisk:['kalisk adulte'],bud:['bud juvenile'], 'bone-bison':['bone bison'],vulture:['vulture'],
 'luna-bug':['luna bug'], 'spray-snake':['spray snake'],'exploding-worm':['exploding worm','ver explosif'],squirt:['squirt'],
};
export function recentFaunaVariantsV85(speciesId:string):readonly RecentSpriteSourceV85[]{
 const names=faunaNames[speciesId];if(!names)return[];
 return RECENT_SPRITE_ASSETS_V85.filter(asset=>asset.packId.startsWith('badlands')&&asset.kind==='fauna'
  &&(names.some(name=>normalizeRecentSpriteTextV85(asset.label).startsWith(name))
   // V14 labels distinguish folded wings and frontal attack, while the
   // source manifest names the same species exactly. Do not broaden other
   // species: Kalisk adult and Bud juvenile still need their own age binding.
   ||(speciesId==='vulture'&&normalizeRecentSpriteTextV85(asset.canonicalSubject??'')==='vulture')));
}
